RETIRED_CACHE = "package com.freedom.adapters.accessibility.diagnostics\n\nimport com.freedom.core.accessibility.api.AccessibilityTreeSnapshot\nimport com.freedom.core.accessibility.diagnostics.NodeCaptureSource\n\n/** In-memory snapshots kept separately by capture origin; no node content is written to preferences. */\nobject LatestAccessibilityNodeDump {\n    @Volatile\n    private var latestManualSnapshots: List<AccessibilityTreeSnapshot> = emptyList()\n    @Volatile\n    private var latestAutomaticSnapshots: List<AccessibilityTreeSnapshot> = emptyList()\n\n    fun update(snapshot: AccessibilityTreeSnapshot, source: NodeCaptureSource = NodeCaptureSource.AUTOMATIC) =\n        updateAll(listOf(snapshot), source)\n\n    fun updateAll(snapshots: List<AccessibilityTreeSnapshot>, source: NodeCaptureSource) {\n        val detached = snapshots.toList()\n        when (source) {\n            NodeCaptureSource.MANUAL -> latestManualSnapshots = detached\n            NodeCaptureSource.AUTOMATIC -> latestAutomaticSnapshots = detached\n        }\n    }\n\n    fun latest(source: NodeCaptureSource): AccessibilityTreeSnapshot? = latestAll(source).firstOrNull()\n\n    fun latestAll(source: NodeCaptureSource): List<AccessibilityTreeSnapshot> = when (source) {\n        NodeCaptureSource.MANUAL -> latestManualSnapshots\n        NodeCaptureSource.AUTOMATIC -> latestAutomaticSnapshots\n    }\n\n    fun clear() {\n        latestManualSnapshots = emptyList()\n        latestAutomaticSnapshots = emptyList()\n    }\n}\n"


def restore_d01d3_source(path, source):
    from tools.architecture.test_pp_r10a_child_component_evidence import ADAPTER as R10A_ADAPTER, restore_r10a_source
    if path == R10A_ADAPTER and git_blob(source.encode("utf-8")) != CURRENT[path]:
        source = restore_r10a_source(path, source)
    for index, current, previous in EDITS[path]:
        if source[index:index + len(current)] != current:
            raise AssertionError("D01-D3 inverse anchor changed: " + path)
        source = source[:index] + previous + source[index + len(current):]
    if git_blob(source.encode("utf-8")) != PREVIOUS[path]:
        raise AssertionError("D01-D3 baseline not reconstructed: " + path)
    return source


def retired_cache_evidence():
    if (ROOT / CACHE).exists() or (ROOT / CACHE).is_symlink():
        raise AssertionError("Retired cache was reintroduced")
    if git_blob(RETIRED_CACHE.encode("utf-8")) != PREVIOUS[CACHE]:
        raise AssertionError("D01-D3 historical cache evidence changed")
    return RETIRED_CACHE


class D01d3LegacyNodeCacheRetirementTest(unittest.TestCase):
    def test_exact_authorized_migration_and_cache_retirement(self):
        for path in EDITS:
            source = (ROOT / path).read_text(encoding="utf-8")
            from tools.architecture.test_pp_r10a_child_component_evidence import AFTER as R10A_AFTER
            self.assertEqual(R10A_AFTER.get(path, CURRENT[path]), git_blob(source.encode("utf-8")))
            self.assertEqual(PREVIOUS[path], git_blob(restore_d01d3_source(path, source).encode("utf-8")))
        self.assertEqual(PREVIOUS[CACHE], git_blob(retired_cache_evidence().encode("utf-8")))

    def test_retired_broadcasts_callbacks_and_cache_absent_from_production(self):
        retired = re.compile(r"\b(?:LatestAccessibilityNodeDump|ACTION_MANUAL_NODE_CAPTURE|ACTION_HIGHLIGHT_NODE_BOUNDS|ACTION_SHOW_NODE_LAYOUT_BOUNDS|ACTION_CLEAR_NODE_BOUNDS_HIGHLIGHT|EXTRA_NODE_CAPTURE_SOURCE|EXTRA_NODE_PATH|EXTRA_NODE_WINDOW_ID|captureManual|onNodeTreeSnapshot|onSnapshotCaptured|onSnapshotsCaptured)\b")
        issues = []
        for path in ROOT.rglob("*"):
            if not path.is_file() or path.suffix not in {".kt", ".java", ".xml", ".aidl", ".json", ".properties", ".kts"}:
                continue
            parts = path.relative_to(ROOT).parts
            if "src" not in parts or "main" not in parts or "build" in parts or ".git" in parts or ".gradle" in parts:
                continue
            if retired.search(path.read_text(encoding="utf-8")):
                issues.append(str(path.relative_to(ROOT)))
        self.assertEqual([], issues)

    def test_live_capture_monitor_and_archive_remain_separate(self):
        service = (ROOT / SERVICE).read_text(encoding="utf-8")
        for action in ("ACTION_SHOW_GLOBAL_NODE_LAYOUT_BOUNDS", "ACTION_SHOW_GLOBAL_NODE_HIERARCHY", "ACTION_CLEAR_GLOBAL_NODE_LAYOUT_BOUNDS"):
            self.assertEqual(2, service.count("MonitorActions." + action), action)
        self.assertIn("globalNodeLayoutVisualizationUseCase.show()", service)
        self.assertIn("globalNodeLayoutVisualizationUseCase.snapshots()", service)
        self.assertIn("accessibilityEventForwarder.accept(event)", service)
        preview = (ROOT / PREVIEW).read_text(encoding="utf-8")
        self.assertIn("if (!isRunning()) return", preview)
        self.assertIn("gateway.inspectActiveWindow(request)", preview)
        self.assertIn("textCapture = NodeTextCapture.NONE", preview)
        self.assertIn("snapshotRepository.save(", preview)
        self.assertNotIn("inspectTargetWindows(", preview)
        adapter = (ROOT / ADAPTER).read_text(encoding="utf-8")
        self.assertIn("sessionComponents.sampleStore.recordNodeTree(", adapter)
        composition = (ROOT / COMPOSITION).read_text(encoding="utf-8")
        self.assertIn("onBrowseEventLogged = { monitorPreviewScheduler.scheduleBrowseScan() }", composition)
        self.assertIn("scanActiveWindow = { accessibilityTreePreviewUseCase.scanActiveWindow() }", composition)

    def test_inverse_rejects_live_safety_mutations(self):
        for path, token in ((SERVICE, "accessibilityEventForwarder.accept(event)"), (SERVICE, "globalNodeLayoutVisualizationUseCase.clear()"), (PREVIEW, "if (!isRunning()) return"), (ADAPTER, "sessionComponents.sampleStore.recordNodeTree("), (COMPOSITION, "monitorPreviewScheduler.scheduleBrowseScan()")):
            source = (ROOT / path).read_text(encoding="utf-8")
            self.assertIn(token, source)
            with self.assertRaises(AssertionError):
                restore_d01d3_source(path, source.replace(token, "BROKEN", 1))
